import unittest, tempfile
from hyperweave import Memory

class MemoryTests(unittest.TestCase):
 def setUp(self):
  self.tmp=tempfile.TemporaryDirectory(); self.m=Memory(self.tmp.name+'/memory.db')
 def tearDown(self): self.m.close(); self.tmp.cleanup()
 def test_provenance_required(self):
  with self.assertRaises(ValueError): self.m.assert_fact('a','related','b',source='')
 def test_conflicts_preserved(self):
  self.m.assert_fact('a','status','open',source='doc:1')
  self.m.assert_fact('a','status','closed',source='doc:2')
  self.assertEqual(len(self.m.conflicts()),1)
  self.assertEqual(len(self.m.query('a')),2)
 def test_scope_isolation(self):
  self.m.assert_fact('a','secret','x',source='doc:1',scope='private')
  self.assertEqual(self.m.query('a',scopes={'public'}),[])
  self.assertEqual(len(self.m.query('a',scopes={'private'})),1)
 def test_hyperedge(self):
  self.m.link('e1',{'cause':'a','effect':'b','context':'c'},source='doc:1')
  self.assertEqual(len(self.m.edges('b')),1)
 def test_idempotence(self):
  a=self.m.assert_fact('a','status','open',source='doc:1')
  b=self.m.assert_fact('a','status','open',source='doc:1')
  self.assertEqual(a,b)
 def test_repair_does_not_delete_evidence(self):
  self.m.assert_fact('a','status','open',source='doc:1')
  self.m.assert_fact('a','status','closed',source='doc:2')
  self.assertEqual(self.m.repair_report()['conflicts'],1)
  self.assertEqual(len(self.m.query('a')),2)
if __name__=='__main__': unittest.main()
