"""HYPERWEAVE: evidence-first hypergraph memory prototype (standard library)."""
import sqlite3, json, hashlib

class Memory:
 def __init__(self,path):
  self.db=sqlite3.connect(path)
  self.db.row_factory=sqlite3.Row
  self.db.executescript('''CREATE TABLE IF NOT EXISTS facts(id TEXT PRIMARY KEY,subject TEXT,predicate TEXT,object TEXT,source TEXT,scope TEXT,valid_from TEXT,valid_to TEXT,recorded_at TEXT DEFAULT CURRENT_TIMESTAMP);
  CREATE TABLE IF NOT EXISTS hyperedges(id TEXT PRIMARY KEY,roles TEXT NOT NULL,source TEXT NOT NULL,scope TEXT NOT NULL,recorded_at TEXT DEFAULT CURRENT_TIMESTAMP);''')
 def close(self): self.db.close()
 def _id(self,*items): return hashlib.sha256(json.dumps(items,sort_keys=True).encode()).hexdigest()[:24]
 def assert_fact(self,subject,predicate,object,*,source,scope='public',valid_from=None,valid_to=None):
  if not source or not str(source).strip(): raise ValueError('source required')
  if not all((subject,predicate,object,scope)): raise ValueError('subject, predicate, object, scope required')
  fid=self._id(subject,predicate,object,source,scope,valid_from,valid_to)
  with self.db: self.db.execute('INSERT OR IGNORE INTO facts(id,subject,predicate,object,source,scope,valid_from,valid_to) VALUES(?,?,?,?,?,?,?,?)',(fid,subject,predicate,object,source,scope,valid_from,valid_to))
  return fid
 def query(self,subject,*,scopes=None):
  if scopes is None: raise ValueError('explicit authorized scopes required')
  if not scopes: return []
  placeholders=','.join('?' for _ in scopes)
  return [dict(r) for r in self.db.execute('SELECT * FROM facts WHERE subject=? AND scope IN ('+placeholders+') ORDER BY recorded_at,id',(subject,*sorted(scopes)))]
 def link(self,id,roles,*,source,scope='public'):
  if not source or not roles or len(roles)<2: raise ValueError('source and >=2 roles required')
  data=json.dumps(roles,sort_keys=True)
  with self.db: self.db.execute('INSERT OR IGNORE INTO hyperedges(id,roles,source,scope) VALUES(?,?,?,?)',(id,data,source,scope))
  return id
 def edges(self,node,*,scopes=None):
  if scopes is None: raise ValueError('explicit authorized scopes required')
  if not scopes:return []
  rows=self.db.execute('SELECT * FROM hyperedges').fetchall()
  return [dict(r)|{'roles':json.loads(r['roles'])} for r in rows if r['scope'] in scopes and node in json.loads(r['roles']).values()]
 def conflicts(self,*,scopes=None):
  if scopes is None: scopes={'public'}
  if not scopes:return []
  ph=','.join('?' for _ in scopes)
  rows=self.db.execute('SELECT subject,predicate,COUNT(DISTINCT object) AS variants FROM facts WHERE scope IN ('+ph+') GROUP BY subject,predicate HAVING variants>1',tuple(sorted(scopes))).fetchall()
  return [dict(r) for r in rows]
 def repair_report(self,*,scopes=None):
  return {'conflicts':len(self.conflicts(scopes=scopes)), 'action':'quarantine_for_review','automatic_deletions':0}
