# Version 0.2 additions: temporal queries, source lineage and integrity auditing.
from datetime import datetime, timezone

def _instant(value):
 if not isinstance(value,str): raise ValueError('timestamp must be an ISO-8601 string')
 try:
  d=datetime.fromisoformat(value.replace('Z','+00:00'))
  if d.tzinfo is None: raise ValueError('timezone required')
  return d.astimezone(timezone.utc)
 except (TypeError,ValueError) as exc: raise ValueError('invalid timezone-aware timestamp') from exc

_old_assert_fact=Memory.assert_fact
def _assert_fact_v02(self,subject,predicate,object,*,source,scope='public',valid_from=None,valid_to=None):
 if valid_from is not None: _instant(valid_from)
 if valid_to is not None: _instant(valid_to)
 if valid_from and valid_to and _instant(valid_from)>=_instant(valid_to): raise ValueError('valid_from must precede valid_to')
 return _old_assert_fact(self,subject,predicate,object,source=source,scope=scope,valid_from=valid_from,valid_to=valid_to)
Memory.assert_fact=_assert_fact_v02

def _snapshot(self,subject,*,at,scopes=None):
 t=_instant(at)
 return [r for r in self.query(subject,scopes=scopes) if (r['valid_from'] is None or _instant(r['valid_from'])<=t) and (r['valid_to'] is None or t<_instant(r['valid_to']))]
Memory.snapshot=_snapshot

def _conflicts_at(self,at,*,scopes=None):
 if scopes is None: raise ValueError('explicit scopes required')
 _instant(at)
 if not scopes:return []
 ph=','.join('?' for _ in scopes)
 subjects=[r[0] for r in self.db.execute('SELECT DISTINCT subject FROM facts WHERE scope IN ('+ph+')',tuple(sorted(scopes)))]
 result=[]
 for subject in subjects:
  groups={}
  for r in self.snapshot(subject,at=at,scopes=scopes): groups.setdefault((r['scope'],r['predicate']),set()).add(r['object'])
  result.extend({'subject':subject,'predicate':predicate,'scope':scope,'variants':len(values)} for (scope,predicate),values in groups.items() if len(values)>1)
 return sorted(result,key=lambda r:(r['subject'],r['predicate'],r['scope']))
Memory.conflicts_at=_conflicts_at

def _lineage(self,source,*,scopes=None):
 if scopes is None: raise ValueError('explicit scopes required')
 if not scopes:return {'facts':[],'hyperedges':[]}
 ph=','.join('?' for _ in scopes)
 args=(source,*sorted(scopes))
 facts=[dict(r) for r in self.db.execute('SELECT * FROM facts WHERE source=? AND scope IN ('+ph+') ORDER BY id',args)]
 edges=[dict(r) for r in self.db.execute('SELECT * FROM hyperedges WHERE source=? AND scope IN ('+ph+') ORDER BY id',args)]
 return {'facts':facts,'hyperedges':edges}
Memory.lineage=_lineage

_old_link=Memory.link
def _link_v02(self,id,roles,*,source,scope='public'):
 existing=self.db.execute('SELECT roles,source,scope FROM hyperedges WHERE id=?',(id,)).fetchone()
 if existing and (json.loads(existing['roles'])!=roles or existing['source']!=source or existing['scope']!=scope): raise ValueError('hyperedge ID collision')
 return _old_link(self,id,roles,source=source,scope=scope)
Memory.link=_link_v02

def _integrity_report(self):
 damaged=[]
 for r in self.db.execute('SELECT * FROM facts'):
  expected=self._id(r['subject'],r['predicate'],r['object'],r['source'],r['scope'],r['valid_from'],r['valid_to'])
  if expected!=r['id']:damaged.append(r['id'])
 return {'ok':not damaged,'mismatched_fact_ids':damaged,'checked_facts':self.db.execute('SELECT COUNT(*) FROM facts').fetchone()[0]}
Memory.integrity_report=_integrity_report
